// ==== perfil.js ====
/* static/js/modules/pasta_painel/modulos/perfil/perfil.js
============================================
PERFIL — usa Mockup global
============================================ */

(function() {
    'use strict';

    document.addEventListener('DOMContentLoaded', function() {
        const form = document.getElementById('formPerfil');
        if (!form) return;

        const inputUsername = document.getElementById('username');
        const feedbackUsername = document.getElementById('usernameFeedback');
        const inputBio = document.getElementById('bio');
        const bioContador = document.getElementById('bioContador');
        const inputNomeExibicao = document.getElementById('nome_exibicao');
        const inputFoto = document.getElementById('foto');
        const inputRemoverFoto = document.getElementById('remover_foto');
        const fotoPreview = document.getElementById('fotoPreview');
        const btnRemoverFoto = document.getElementById('btnRemoverFoto');
        const btnSalvar = document.getElementById('btnSalvarPerfilFooter');  // ← ID NOVO
        const inputFotoPosicao = document.getElementById('foto_posicao');

        function atualizarMockup() {
            if (!window.Mockup) return;
            if (inputNomeExibicao) Mockup.setNome(inputNomeExibicao.value.trim());
            if (inputBio) Mockup.setBio(inputBio.value.trim());
        }

        // USERNAME (validação)
        let timeoutUsername = null;
        if (inputUsername) {
            inputUsername.addEventListener('input', function() {
                const username = this.value.trim().toLowerCase();
                this.value = username;
                clearTimeout(timeoutUsername);

                if (!username) {
                    feedbackUsername.textContent = 'Letras minúsculas, números e _.';
                    feedbackUsername.className = 'form-hint';
                    return;
                }
                if (username.length < 3) {
                    feedbackUsername.textContent = 'Mínimo 3 caracteres.';
                    feedbackUsername.className = 'form-hint form-hint-erro';
                    return;
                }
                if (!/^[a-z][a-z0-9_]*$/.test(username)) {
                    feedbackUsername.textContent = 'Só minúsculas, números e _ (começar com letra).';
                    feedbackUsername.className = 'form-hint form-hint-erro';
                    return;
                }

                feedbackUsername.textContent = 'Verificando...';
                feedbackUsername.className = 'form-hint form-hint-verificando';

                timeoutUsername = setTimeout(() => {
                    fetch('/painel/perfil/verificar-username/' + encodeURIComponent(username))
                        .then(r => r.json())
                        .then(data => {
                            if (data.disponivel) {
                                feedbackUsername.textContent = '✅ Disponível!';
                                feedbackUsername.className = 'form-hint form-hint-ok';
                            } else {
                                feedbackUsername.textContent = '❌ ' + (data.message || 'Indisponível.');
                                feedbackUsername.className = 'form-hint form-hint-erro';
                            }
                        })
                        .catch(() => {
                            feedbackUsername.textContent = 'Erro ao verificar.';
                            feedbackUsername.className = 'form-hint form-hint-erro';
                        });
                }, 500);
            });
        }

        // NOME
        if (inputNomeExibicao) {
            inputNomeExibicao.addEventListener('input', atualizarMockup);
        }

        // BIO
        if (inputBio && bioContador) {
            const atualizar = () => {
                bioContador.textContent = inputBio.value.length;
                atualizarMockup();
            };
            inputBio.addEventListener('input', atualizar);
            atualizar();
        }

        // POSIÇÃO DO CORTE
        if (inputFotoPosicao) {
            inputFotoPosicao.addEventListener('change', function() {
                const preview = document.getElementById('fotoPreview');
                if (preview) {
                    const img = preview.querySelector('img');
                    if (img) {
                        img.style.objectPosition = 'center ' + this.value;
                    }
                }
                if (window.Mockup && Mockup.setFotoPosicao) {
                    Mockup.setFotoPosicao(this.value);
                }
            });
        }

        // FOTO — upload
        if (inputFoto) {
            inputFoto.addEventListener('change', function() {
                const file = this.files[0];
                if (!file) return;

                if (file.size > 2 * 1024 * 1024) {
                    if (window.Notificacao) Notificacao.erro('Imagem muito grande. Máximo 2MB.');
                    this.value = '';
                    return;
                }

                const reader = new FileReader();
                reader.onload = (e) => {
                    const src = e.target.result;
                    const posicao = inputFotoPosicao ? inputFotoPosicao.value : 'top';

                    if (fotoPreview) {
                        fotoPreview.innerHTML = `<img src="${src}" alt="Preview" style="object-position: center ${posicao};">`;
                    }
                    if (window.Mockup) {
                        Mockup.setFoto(src);
                    }
                };
                reader.readAsDataURL(file);

                if (inputRemoverFoto) inputRemoverFoto.value = '0';
                if (btnRemoverFoto) btnRemoverFoto.disabled = false;
            });
        }

        // FOTO — remover
        if (btnRemoverFoto) {
            btnRemoverFoto.addEventListener('click', function() {
                if (inputRemoverFoto) inputRemoverFoto.value = '1';
                if (inputFoto) inputFoto.value = '';

                const placeholder = '<div class="pp-foto-placeholder"><i class="fas fa-user"></i></div>';
                if (fotoPreview) fotoPreview.innerHTML = placeholder;

                if (window.Mockup) Mockup.setFoto(null);

                btnRemoverFoto.disabled = true;

                if (window.Notificacao) {
                    Notificacao.aviso('Foto marcada pra remoção. Salva pra confirmar.');
                }
            });
        }

        // ⚠️ BOTÃO DO FOOTER: chama submit do form
        if (btnSalvar) {
            btnSalvar.addEventListener('click', function() {
                form.requestSubmit();
            });
        }

        // SUBMIT
        form.addEventListener('submit', function(ev) {
            ev.preventDefault();

            const formData = new FormData(form);

            // Loading no botão do footer
            if (btnSalvar) {
                btnSalvar.disabled = true;
                const texto = btnSalvar.querySelector('span');
                if (texto) texto.textContent = 'SALVANDO...';
            }

            fetch('/painel/perfil/salvar', {
                method: 'POST',
                body: formData,
                headers: { 'X-Requested-With': 'XMLHttpRequest' }
            })
            .then(r => r.json().then(j => ({ ok: r.ok, data: j })))
            .then(({ ok, data }) => {
                if (!ok || !data.success) {
                    const msg = data.error || 'Erro ao salvar.';
                    if (window.Notificacao) Notificacao.erro(msg);
                    return;
                }
                if (window.Notificacao) Notificacao.sucesso(data.message || 'Perfil atualizado!');

                if (inputRemoverFoto) inputRemoverFoto.value = '0';
                if (btnRemoverFoto) btnRemoverFoto.disabled = true;
            })
            .catch(() => {
                if (window.Notificacao) Notificacao.erro('Erro de conexão.');
            })
            .finally(() => {
                if (btnSalvar) {
                    btnSalvar.disabled = false;
                    const texto = btnSalvar.querySelector('span');
                    if (texto) texto.textContent = 'SALVAR';
                }
            });
        });

        atualizarMockup();
        console.log('✅ Perfil carregado');
    });
})();

// ==== aparencia.js ====
/* static/js/modules/pasta_painel/modulos/aparencia/aparencia.js
   Rascunho ao vivo preservado. SEM merge no cliente — o que tá no input É o config.
   O template só PRE-POPULA. O merge real acontece no backend (AparenciaFinalService).
*/
(function () {
    'use strict';

    document.addEventListener('DOMContentLoaded', function () {
        const form = document.getElementById('formAparencia');
        if (!form) return;

        const $ = (id) => document.getElementById(id);

        const inputCorPrimaria    = $('cor_primaria');
        const inputCorSecundaria  = $('cor_secundaria');
        const inputCorFundo       = $('cor_fundo');
        const inputCorTexto       = $('cor_texto');
        const inputFonte          = $('fonte');
        const inputEstiloBotao    = $('estilo_botao');
        const inputTamanhoFoto    = $('tamanho_foto');
        const inputTamanhoLink    = $('tamanho_link');
        const inputEspacamento    = $('espacamento_links');
        const inputBordaLink      = $('borda_link');
        const inputHoverEfeito    = $('hover_efeito');
        const inputAnimacaoEntrada= $('animacao_entrada');
        const inputTemplateSlug   = $('template_slug_hidden');

        const btnSalvarFooter     = $('btnSalvarFooter');

        const hexPrimaria   = $('corPrimariaHex');
        const hexSecundaria = $('corSecundariaHex');
        const hexFundo      = $('corFundoHex');
        const hexTexto      = $('corTextoHex');

        // ===== CONFIG USER (o que tá no input É o config) =====
        function pegarConfigUser() {
            return {
                cores: {
                    primaria:   inputCorPrimaria?.value,
                    secundaria: inputCorSecundaria?.value,
                    fundo:      inputCorFundo?.value,
                    texto:      inputCorTexto?.value,
                },
                tipografia: {
                    fonte:        inputFonte?.value,
                    estilo_botao: inputEstiloBotao?.value,
                },
                layout: {
                    tamanho_foto:       inputTamanhoFoto?.value,
                    tamanho_link:       inputTamanhoLink?.value,
                    espacamento_links:  inputEspacamento?.value,
                    borda_link:         inputBordaLink?.value,
                },
                efeitos: {
                    hover_efeito:     inputHoverEfeito?.value,
                    animacao_entrada: inputAnimacaoEntrada?.value,
                },
            };
        }

        // ===== APLICA NO PREVIEW (sem merge — input é verdade) =====
        function atualizarMockup() {
            if (!window.Mockup) return;
            window.Mockup.aplicar(pegarConfigUser());
        }

        // ===== LISTENERS DE CORES (input + change, todos navegadores) =====
        [
            { el: inputCorPrimaria,   hex: hexPrimaria },
            { el: inputCorSecundaria, hex: hexSecundaria },
            { el: inputCorFundo,      hex: hexFundo },
            { el: inputCorTexto,      hex: hexTexto },
        ].forEach(function (par) {
            if (!par.el) return;
            const handler = function () {
                if (par.hex) par.hex.textContent = par.el.value;
                atualizarMockup();
            };
            par.el.addEventListener('input',  handler);
            par.el.addEventListener('change', handler);
        });

        // ===== LISTENERS DE ESTILO =====
        [
            inputFonte, inputEstiloBotao,
            inputTamanhoFoto, inputTamanhoLink, inputEspacamento,
            inputBordaLink, inputHoverEfeito, inputAnimacaoEntrada,
        ].forEach(function (el) {
            if (el) el.addEventListener('change', atualizarMockup);
        });

        // ===== TEMPLATES — pré-popula os inputs =====
        document.querySelectorAll('.template-card').forEach(function (card) {
            card.addEventListener('click', function () {
                document.querySelectorAll('.template-card').forEach(c => c.classList.remove('active'));
                this.classList.add('active');

                const slug = this.dataset.template;
                if (inputTemplateSlug) inputTemplateSlug.value = slug;

                let configDefault = {};
                try { configDefault = JSON.parse(this.dataset.config || '{}'); } catch (e) {}

                const cores = configDefault.cores || {};
                if (inputCorPrimaria   && cores.primaria)   { inputCorPrimaria.value   = cores.primaria;   if (hexPrimaria)   hexPrimaria.textContent   = cores.primaria; }
                if (inputCorSecundaria && cores.secundaria) { inputCorSecundaria.value = cores.secundaria; if (hexSecundaria) hexSecundaria.textContent = cores.secundaria; }
                if (inputCorFundo      && cores.fundo)      { inputCorFundo.value      = cores.fundo;      if (hexFundo)      hexFundo.textContent      = cores.fundo; }
                if (inputCorTexto      && cores.texto)      { inputCorTexto.value      = cores.texto;      if (hexTexto)      hexTexto.textContent      = cores.texto; }

                const tipografia = configDefault.tipografia || {};
                if (inputFonte       && tipografia.fonte)        inputFonte.value       = tipografia.fonte;
                if (inputEstiloBotao && tipografia.estilo_botao) inputEstiloBotao.value = tipografia.estilo_botao;

                const layout = configDefault.layout || {};
                if (inputTamanhoFoto && layout.tamanho_foto)       inputTamanhoFoto.value = layout.tamanho_foto;
                if (inputTamanhoLink && layout.tamanho_link)       inputTamanhoLink.value = layout.tamanho_link;
                if (inputEspacamento && layout.espacamento_links)  inputEspacamento.value = layout.espacamento_links;
                if (inputBordaLink   && layout.borda_link)         inputBordaLink.value   = layout.borda_link;

                const efeitos = configDefault.efeitos || {};
                if (inputHoverEfeito     && efeitos.hover_efeito)     inputHoverEfeito.value     = efeitos.hover_efeito;
                if (inputAnimacaoEntrada && efeitos.animacao_entrada) inputAnimacaoEntrada.value = efeitos.animacao_entrada;

                atualizarMockup();
            });
        });

        // ===== SUBMIT =====
        function submeter() {
            const templateSlug = inputTemplateSlug?.value || 'cosmic';
            const config       = pegarConfigUser();

            if (btnSalvarFooter) {
                btnSalvarFooter.disabled = true;
                const icone = btnSalvarFooter.querySelector('i');
                if (icone) icone.className = 'fas fa-spinner fa-spin';
            }

            fetch('/painel/aparencia/salvar', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                    'X-Requested-With': 'XMLHttpRequest',
                },
                body: JSON.stringify({ template_slug: templateSlug, config: config }),
            })
            .then(r => r.json().then(j => ({ ok: r.ok, data: j })))
            .then(({ ok, data }) => {
                if (!ok || !data.success) {
                    if (window.Notificacao) Notificacao.erro(data.error || 'Erro ao salvar.');
                    return;
                }
                if (window.Notificacao) Notificacao.sucesso(data.message || 'Aparência atualizada!');
            })
            .catch(() => {
                if (window.Notificacao) Notificacao.erro('Erro de conexão.');
            })
            .finally(() => {
                if (btnSalvarFooter) {
                    btnSalvarFooter.disabled = false;
                    const icone = btnSalvarFooter.querySelector('i');
                    if (icone) icone.className = 'fas fa-save';
                }
            });
        }

        form.addEventListener('submit', function (ev) { ev.preventDefault(); submeter(); });
        if (btnSalvarFooter) btnSalvarFooter.addEventListener('click', submeter);

        // ===== INICIALIZA =====
        atualizarMockup();
        console.log('✅ Aparência carregada (input = config, sem merge no cliente)');
    });
})();

// ==== config.js ====
/* static/js/modules/pasta_painel/modulos/config/config.js
============================================
CONFIGURAÇÕES — alterar senha
============================================ */

(function() {
    'use strict';

    const form = document.getElementById('formAlterarSenha');
    if (!form) return;

    const btnAlterar = document.getElementById('btnAlterarSenha');
    const btnDeletar = document.getElementById('btnDeletarConta');

    // ==========================================================
    // ALTERAR SENHA
    // ==========================================================
    form.addEventListener('submit', function(ev) {
        ev.preventDefault();
        const formData = new FormData(form);

        if (btnAlterar) {
            btnAlterar.classList.add('loading');
            btnAlterar.disabled = true;
        }

        fetch('/painel/configuracoes/alterar-senha', {
            method: 'POST',
            body: formData,
            headers: { 'X-Requested-With': 'XMLHttpRequest' }
        })
        .then(r => r.json().then(j => ({ ok: r.ok, data: j })))
        .then(({ ok, data }) => {
            if (!ok || !data.success) {
                Notificacao.erro(data.error || 'Erro ao alterar senha.');
                return;
            }
            Notificacao.sucesso(data.message || 'Senha alterada!');
            form.reset();
        })
        .catch(() => Notificacao.erro('Erro de conexão.'))
        .finally(() => {
            if (btnAlterar) {
                btnAlterar.classList.remove('loading');
                btnAlterar.disabled = false;
            }
        });
    });

    // ==========================================================
    // DELETAR CONTA (placeholder — futuro)
    // ==========================================================
    if (btnDeletar) {
        btnDeletar.addEventListener('click', function() {
            Notificacao.aviso('Função em desenvolvimento. Fale com o suporte.');
        });
    }

    console.log('✅ Config carregado');

})();

